def amicable_numbers_sum(limit):
    def sum_of_divisors(n):
        """Calculate the sum of proper divisors of n."""
        divisors = [1]  # 1 is a proper divisor of every number > 1
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                divisors.append(i)
                if i != n // i:  # Avoid adding the square root twice
                    divisors.append(n // i)
        return sum(divisors)

    amicable_sum = 0
    for a in range(2, limit + 1):
        b = sum_of_divisors(a)
        if b != a and b <= limit and sum_of_divisors(b) == a:
            amicable_sum += a

    return amicable_sum

# Example usage
assert amicable_numbers_sum(999) == 504
```

