def find_length(binary_string):
    def max_diff_zeros_ones(binary_string):
        max_diff = 0
        current_diff = 0

        for char in binary_string:
            if char == '0':
                current_diff += 1  # Treat '0' as +1
            else:
                current_diff -= 1  # Treat '1' as -1

            max_diff = max(max_diff, current_diff)

            if current_diff < 0:
                current_diff = 0  # Reset if the difference becomes negative

        return max_diff

    # Replace all '0's with +1 and '1's with -1, then find max subarray sum
    return max_diff_zeros_ones(binary_string)
