def check_occurences(tuple_list):
    result = {}
    for t in tuple_list:
        # Ensure tuples are normalized (sorted) so (3, 1) and (1, 3) are treated the same
        normalized_tuple = tuple(sorted(t))
        if normalized_tuple in result:
            result[normalized_tuple] += 1
        else:
            result[normalized_tuple] = 1
    return result
