def sequential_search(array, element):
    """
    This function takes in an array and an element, and returns a tuple containing:
    - A boolean indicating whether the element is in the array.
    - The index of the element in the array, or -1 if the element is not found.
    """
    for index, value in enumerate(array):
        if value == element:
            return (True, index)
    return (False, -1)

