def max_aggregate(data):
    # Create a dictionary to store aggregate scores
    aggregates = {}

    # Iterate through the list of tuples
    for name, score in data:
        if name in aggregates:
            aggregates[name] += score  # Add score to the existing total
        else:
            aggregates[name] = score  # Initialize total for the name

    # Find the name with the maximum aggregate score
    max_name = max(aggregates, key=aggregates.get)
    return (max_name, aggregates[max_name])

# Test case
assert max_aggregate([('Juan Whelan',90),('Sabah Colley',88),('Peter Nichols',7),('Juan Whelan',122),('Sabah Colley',84)]) == ('Juan Whelan', 212)
```

