def find_kth(arr1, arr2, k):
    def kth_helper(a, b, k):
        if not a:
            return b[k - 1]
        if not b:
            return a[k - 1]
        if k == 1:
            return min(a[0], b[0])

        mid_a = k // 2 - 1 if len(a) >= k // 2 else len(a) - 1
        mid_b = k // 2 - 1 if len(b) >= k // 2 else len(b) - 1

        if a[mid_a] <= b[mid_b]:
            return kth_helper(a[mid_a + 1:], b, k - (mid_a + 1))
        else:
            return kth_helper(a, b[mid_b + 1:], k - (mid_b + 1))

    return kth_helper(arr1, arr2, k)

# Example usage:
assert find_kth([2, 3, 6, 7, 9], [1, 4, 8, 10], 5) == 6
```

