def count_Substrings(s):
    def digit_sum(substring):
        return sum(int(char) for char in substring)

    n = len(s)
    count = 0

    for i in range(n):
        current_sum = 0
        for j in range(i, n):
            current_sum += int(s[j])
            if current_sum == (j - i + 1):  # Sum of digits equals length of substring
                count += 1

    return count

