def merge_dictionaries_three(dict1, dict2, dict3):
    """
    Merges three dictionaries into a single dictionary.
    In case of key collisions, values from the last dictionary take precedence.
    """
    # Use dictionary unpacking to merge dictionaries.
    merged_dict = {**dict1, **dict2, **dict3}
    return merged_dict

